@Test func productWithoutItemsCanBeDeleted() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = Product(name: "しょうゆ", type: "調味料")
    context.insert(product)
    try context.save()

    let reader = ModelContext(container)
    let items = try reader.fetch(ProductDetailView.itemDescriptor(for: product.id))
    let counts = ProductDeletionCounts(items: items)

    #expect(counts.unopened == 0)
    #expect(counts.inUse == 0)
    #expect(counts.history == 0)
    #expect(counts.unknown == 0)
    #expect(counts.canDelete)
}

@Test func deletionCountsIncludeEveryStateAndExcludeOtherProducts() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = Product(name: "しょうゆ", type: "調味料")
    let other = Product(name: "しょうゆ", type: "調味料")
    context.insert(product)
    context.insert(other)
    let states = ["unopened", "unopened", "inUse", "consumed", "consumed", "consumed", "future"]
    for state in states {
        let item = Item(product: product)
        item.statusRawValue = state
        context.insert(item)
    }
    context.insert(Item(product: other))
    try context.save()

    let reader = ModelContext(container)
    let items = try reader.fetch(ProductDetailView.itemDescriptor(for: product.id))
    let counts = ProductDeletionCounts(items: items)

    #expect(items.count == states.count)
    #expect(items.allSatisfy { $0.product?.id == product.id })
    #expect(counts.unopened == 2)
    #expect(counts.inUse == 1)
    #expect(counts.history == 3)
    #expect(counts.unknown == 1)
    #expect(!counts.canDelete)
    #expect(!reader.hasChanges)
}

@Test(arguments: [("consumed", 1, 0), ("future", 0, 1)])
func historyOrUnknownStateAlonePreventsDeletion(_ state: String, _ history: Int, _ unknown: Int) throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = Product(name: "しょうゆ", type: "調味料")
    context.insert(product)
    let item = Item(product: product)
    item.statusRawValue = state
    context.insert(item)
    try context.save()

    let reader = ModelContext(container)
    let items = try reader.fetch(ProductDetailView.itemDescriptor(for: product.id))
    let counts = ProductDeletionCounts(items: items)

    #expect(counts.unopened == 0)
    #expect(counts.inUse == 0)
    #expect(counts.history == history)
    #expect(counts.unknown == unknown)
    #expect(!counts.canDelete)
    #expect(items.first?.statusRawValue == state)
}

@MainActor
func testProductDeletionRequiresConfirmationAndSurvivesRelaunch() throws {
    let app = makeApplication()
    app.launch()
    try registerAndOpenDetail(name: "Delete", type: "Type", in: app)

    let unopened = try detailElement("product-detail-unopened", in: app)
    XCTAssertEqual(unopened.label, "未開封、0件")
    let inUse = try detailElement("product-detail-in-use", in: app)
    XCTAssertEqual(inUse.label, "使用中、0件")
    let history = try detailElement("product-detail-history", in: app)
    XCTAssertEqual(history.label, "使い切り履歴、0件")
    let delete = try detailElement("product-detail-delete", in: app)
    XCTAssertTrue(delete.isEnabled)
    delete.tap()

    let confirm = app.buttons["product-detail-confirm-delete"]
    XCTAssertTrue(confirm.waitForExistence(timeout: 5))
    XCTAssertTrue(app.staticTexts["「Delete」の商品情報と画像を削除します。この操作は取り消せません。"].exists)
    app.buttons["キャンセル"].tap()
    XCTAssertTrue(app.navigationBars["商品詳細"].exists)
    app.navigationBars["商品詳細"].buttons["商品一覧"].tap()
    let row = productRow(name: "Delete", type: "Type", in: app)
    XCTAssertTrue(row.waitForExistence(timeout: 5))
    row.tap()

    try detailElement("product-detail-delete", in: app).tap()
    XCTAssertTrue(confirm.waitForExistence(timeout: 5))
    confirm.tap()

    XCTAssertTrue(app.navigationBars["商品一覧"].waitForExistence(timeout: 5))
    XCTAssertTrue(app.staticTexts["商品はまだありません"].waitForExistence(timeout: 5))
    XCTAssertFalse(row.exists)
    app.terminate()
    app.launch()

    XCTAssertTrue(app.navigationBars["商品一覧"].waitForExistence(timeout: 5))
    XCTAssertTrue(app.staticTexts["商品はまだありません"].waitForExistence(timeout: 5))
    XCTAssertFalse(productRow(name: "Delete", type: "Type", in: app).exists)
}

@Environment(\.modelContext) private var modelContext
@Environment(\.dismiss) private var dismiss
@Query private var products: [Product]
@Query private var items: [Item]
@State private var showsDeletionConfirmation = false
@State private var deletionError: String?

init(productID: UUID) {
    _products = Query(Self.descriptor(for: productID))
    _items = Query(Self.itemDescriptor(for: productID))
}

static func descriptor(for productID: UUID) -> FetchDescriptor<Product> {
    var descriptor = FetchDescriptor<Product>(predicate: #Predicate { $0.id == productID })
    descriptor.includePendingChanges = false
    return descriptor
}

static func itemDescriptor(for productID: UUID) -> FetchDescriptor<Item> {
    FetchDescriptor<Item>(predicate: #Predicate { $0.product?.id == productID })
}

@Environment(\.modelContext) private var modelContext
@Environment(\.dismiss) private var dismiss
@Query private var products: [Product]
@Query private var items: [Item]
@State private var showsDeletionConfirmation = false
@State private var deletionError: String?

init(productID: UUID) {
    _products = Query(Self.descriptor(for: productID))
    _items = Query(Self.itemDescriptor(for: productID))

} else if let product = products.first, let detail = ProductDetailContent(product: product) {
    details(detail)
        .confirmationDialog(
            "商品を削除しますか？", isPresented: $showsDeletionConfirmation, titleVisibility: .visible
        ) {
            Button("削除する", role: .destructive) {
                deleteProduct()
            }
            .accessibilityIdentifier("product-detail-confirm-delete")

            Button("キャンセル", role: .cancel) {}
        } message: {
            Text("「\(detail.name)」の商品情報と画像を削除します。この操作は取り消せません。")
        }

private func deleteProduct() {
    guard let product = products.first, !product.isDeleted, product.modelContext === modelContext else {
        deletionError = "商品が見つかりません。一覧に戻って商品を選び直してください。"
        return
    }

    // 確認中に個体が増えていても、保存境界で最新の件数を再検査する。
    switch ProductActions(context: modelContext).delete(product, confirmed: true) {
    case .success:
        dismiss()
    case .failure(let error):
        switch error {
        case .productHasItems(let count):
            deletionError = "個体が\(count)件紐づいているため削除できません。一覧に戻って最新の件数を確認してください。"
        case .pendingChanges:
            deletionError = "ほかの変更が保存されていません。保存が完了してから、もう一度「商品を削除」を押してください。"
        case .productNotInContext:
            deletionError = "商品が見つかりません。一覧に戻って商品を選び直してください。"
        case .persistence(let underlying):
            deletionError = "削除を保存できませんでした。\(underlying.localizedDescription) もう一度「商品を削除」を押してください。"
        case .deletionNotConfirmed, .validation:
            deletionError = "削除できませんでした。一覧に戻って商品を選び直し、もう一度確認してください。"
        }
    }

/// 在庫だけでなく履歴と未知の状態も、削除を妨げる個体として数える。
struct ProductDeletionCounts {
    private(set) var unopened = 0
    private(set) var inUse = 0
    private(set) var history = 0
    private(set) var unknown = 0

    var canDelete: Bool {
        unopened + inUse + history + unknown == 0
    }

    init(items: [Item]) {
        for item in items {
            switch item.status {
            case .unopened?:
                unopened += 1
            case .inUse?:
                inUse += 1
            case .consumed?:
                history += 1
            case nil:
                unknown += 1
            }
        }
    }

private var deletionSection: some View {
    let counts = ProductDeletionCounts(items: items)

    return Section("個体と削除") {
        if let error = _items.fetchError {
            Text("個体の件数を読み込めないため削除できません。\(error.localizedDescription) 一覧に戻って、もう一度商品を選んでください。")
        } else {
            ProductDetailRow(label: "未開封", value: "\(counts.unopened)件")
                .accessibilityIdentifier("product-detail-unopened")
            ProductDetailRow(label: "使用中", value: "\(counts.inUse)件")
                .accessibilityIdentifier("product-detail-in-use")
            ProductDetailRow(label: "使い切り履歴", value: "\(counts.history)件")
                .accessibilityIdentifier("product-detail-history")

            if counts.unknown > 0 {
                ProductDetailRow(label: "不明な状態", value: "\(counts.unknown)件")
            }

            if !counts.canDelete {
                Text("個体が紐づいているため削除できません。使い切り履歴や不明な状態の個体も削除不可の対象です。")
                    .accessibilityIdentifier("product-detail-deletion-reason")
            }
        }

        if let deletionError {
            Text(deletionError)
                .foregroundStyle(.red)
                .accessibilityIdentifier("product-detail-deletion-error")
        }

        Button("商品を削除", role: .destructive) {
            deletionError = nil
            showsDeletionConfirmation = true
        }
        .disabled(_items.fetchError != nil || !counts.canDelete)
        .accessibilityIdentifier("product-detail-delete")
